#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    cin >> N >> M;

    vector<string> grid(N);
    queue<pair<int, int>> q;

    for (int i = 0; i < N; ++i) {
        cin >> grid[i];
        for (int j = 0; j < M; ++j) {
            if (grid[i][j] == 'o') {
                q.push({i, j});
            }
        }
    }

    auto wet = [&](int r, int c) {
        if (r < 0 || r >= N || c < 0 || c >= M || grid[r][c] != '.') {
            return;
        }
        grid[r][c] = 'o';
        q.push({r, c});
    };

    while (!q.empty()) {
        auto [r, c] = q.front();
        q.pop();

        // Water flows downward.
        wet(r + 1, c);

        // Water spreads horizontally when supported by a shelf below.
        if (r + 1 < N && grid[r + 1][c] == '#') {
            wet(r, c - 1);
            wet(r, c + 1);
        }
    }

    for (const string& row : grid) {
        cout << row << '\n';
    }

    return 0;
}
